//! Basic Stellar starter — generate a keypair and print it.
//!
//! Generated by `stellar-qk init --template basic`.
//!
//! ## Run
//!
//! ```
//! cargo run
//! ```

use anyhow::Result;
use stellar_qk::keys::{generate_keypair, validate_key};

fn main() -> Result<()> {
    println!("=== Stellar keypair generator ===\n");

    let kp = generate_keypair();

    println!("Public key  : {}", kp.public_key);
    println!("Secret seed : {}", kp.secret_seed);
    println!();
    println!("⚠  Never share or commit your secret seed.");

    // Demonstrate offline validation
    let key_type = validate_key(&kp.public_key)?;
    println!("\nValidation  : {:?}", key_type);

    Ok(())
}
